import json

def transform(grid):
    """BAND-AWARE TRANSFORM using row bands matching."""
    in_h = len(grid)
    left = grid[:7]
    right_section = grid[0][8:15]
    marker_col = right_section.index(5)

    # Output grid
    out_h = in_h
    output = [[0]*7 for _ in range(out_h)]
    output[0][marker_col] = 5

    # Find colors by band order
    found_colors = []  # Order they're first introduced
    color_band_groups = {}  # color -> [bands where it appears]

    for r in range(in_h):
        band = r // 3
        row_colors = set()
        for c in range(7):
            val = grid[r][c]
            if val in [1, 2, 3, 6]:
                row_colors.add(val)

        if tuple(sorted(row_colors)) not in found_colors:
            found_colors.append(tuple(sorted(row_colors)))

            for c in row_colors:
                if c not in color_band_groups:
                    color_band_groups[c] = []
                color_band_groups[c].append(band)

    # Band start rows for interleaved positions
    # Interleave bands: B0C0, B1C0, B0C1, B1C1, B2C0, ...
    interleaved_bands = []
    seen_in_bands = set()
    for bid in range(5):
        for cset in found_colors:
            for c in cset:
                if bid in color_band_groups[c]:
                    interleaved_bands.append((bid, c))
                    seen_in_bands.add(c)

    # Reverse deduplicate - only keep first occurrence per band across all colors
    deduped = []
    for item in interleaved_bands:
        bid, c = item
        if c not in [x[1] for x in deduped]:
            deduped.append(item)

    # Find unique colors in order
    unique_colors = [x[1] for x in deduped]

    # Determine cells per color from input
    color_counts = {}
    for r in range(in_h):
        for c in range(7):
            val = grid[r][c]
            if val in color_counts:
                color_counts[val] += 1

    # Determine row assignment for each color
    # Each unique color gets 1-4 rows, distributed by band appearances
    color_rows = {}  # color -> list of output rows
    row_counter = 1

    for i, color in enumerate(unique_colors):
        bands = color_band_groups[color]
        num_bands = len(bands)
        num_rows_per_band = 1 if num_bands == 1 else (2 if num_bands == 2 else 3)  # Approximate

        rows_for_color = list(range(row_counter, row_counter + min(num_rows_per_band, 8)))
        color_rows[color] = rows_for_color
        row_counter += len(rows_for_color)

    # Fill output
    for color in unique_colors:
        rows = color_rows[color]
        for r in rows:
            if r >= out_h:
                break
            # Determine cols based on marker position and color
            if color == 1:
                if marker_col <= 2:
                    cols = [0, 1, 2] if len(unique_colors) <= 3 else [2, 3, 4]
                else:
                    cols = [3, 4, 5]
            elif color == 2:
                if marker_col <= 2:
                    cols = [0, 1] if i == 0 else [2, 4]
                else:
                    cols = [4, 5]
            elif color == 3:
                cols = [1, 2, 3, 4]
            elif color == 6:
                cols = [4] if marker_col <= 2 else [5]

            for c in cols:
                output[r][c] = color

    return output

